<template><view class="p"><text class="t">{{title}}</text><view v-if="wrongCount" class="wrong" @click="openWrong">本阶段错题（{{wrongCount}}）›</view><view v-for="x in points" :key="x.id" class="row" @click="open(x)"><view><text class="name">{{x.title}}</text><text class="desc">{{x.description}}</text></view><text>去练习 ›</text></view><view v-if="!points.length" class="empty">{{ emptyText }}</view></view></template><script>import{BASE_URL}from'@/utils/api.js';export default{data(){return{stage:1,points:[],wrongCount:0}},computed:{title(){return ['','基础句型','核心语法','进阶语法'][this.stage]},emptyText(){return this.stage===3?'恭喜你，进阶语法阶段已全部完成！':'本阶段语法已全部完成'}},onLoad(q){this.stage=Number(q.stage)},onShow(){uni.request({url:BASE_URL+'/grammar-point/list?stage='+this.stage,success:r=>{let done=uni.getStorageSync('grammar_done')||[];this.points=(r.data.data||[]).filter(x=>!done.includes(x.id));this.wrongCount=(uni.getStorageSync('grammar_wrong')||[]).filter(q=>Number(q.stage)===this.stage).length}})},methods:{openWrong(){uni.navigateTo({url:'/pages/grammar/wrong?stage='+this.stage})},open(x){uni.navigateTo({url:'/pages/grammar/practice?id='+x.id})}}}</script><style>.p{min-height:100vh;background:#f7f5f0;padding:30rpx}.t,.name{display:block;font-weight:bold;color:#1f3a5f}.t{font-size:40rpx;margin-bottom:25rpx}.row{display:flex;justify-content:space-between;align-items:center;background:#fff;margin-bottom:16rpx;padding:28rpx;border-radius:16rpx;color:#0d9488}.desc{display:block;color:#888;font-size:24rpx;margin-top:8rpx}.wrong{background:#fff1f2;color:#ef4444;padding:18rpx;border-radius:12rpx;margin-bottom:18rpx}.empty{text-align:center;color:#888;padding:100rpx}</style>
